def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)
    out = [row[:] for row in grid]
    # Fill the interiors of triangular outlines whose tip is a lone marker.
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != color:
                continue
            # A tip may point down or up. Confirm the two diagonal sides
            # with markers on each successive row (allowing clipped side cells).
            for direction in (-1, 1):
                levels = 0
                for d in range(1, min(h, w) + 1):
                    rr = r0 + direction*d
                    if not (0 <= rr < h): break
                    left, right = c0-d, c0+d
                    # Each visible side should be marked; a side beyond the
                    # grid edge is naturally clipped.
                    ok = True
                    for cc in (left, right):
                        if 0 <= cc < w and grid[rr][cc] != color:
                            ok = False
                    if not ok: break
                    levels = d
                if levels:
                    for d in range(1, levels+1):
                        rr = r0 + direction*d
                        for cc in range(max(0,c0-d+1), min(w,c0+d)):
                            if out[rr][cc] == 0: out[rr][cc] = 2
    return out
