def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next((v for row in grid for v in row if v), 0)
    out = [row[:] for row in grid]
    for r0 in range(h):
        for c0 in range(w):
            if grid[r0][c0] != color:
                continue
            for dr in (-1, 1):
                d = 1
                while 0 <= r0 + dr*d < h:
                    rr = r0 + dr*d
                    # The two sides of the triangular outline may be clipped at the grid edge.
                    if any(0 <= cc < w and grid[rr][cc] != color for cc in (c0-d, c0+d)):
                        break
                    for cc in range(max(0, c0-d+1), min(w, c0+d)):
                        if out[rr][cc] == 0:
                            out[rr][cc] = 2
                    d += 1
    return out
